class MainActivity : ComponentActivity(), NfcAdapter.ReaderCallback {
    private val model: MainViewModel by viewModels()
    private val adapter by lazy { NfcAdapter.getDefaultAdapter(this) }
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        WindowCompat.getInsetsController(window, window.decorView).isAppearanceLightStatusBars = true
        setContent { SpoolioTheme { SpoolioApp(model, adapter != null) } }
    }
    override fun onResume() { super.onResume(); adapter?.enableReaderMode(this, this, NfcAdapter.FLAG_READER_NFC_A, null) }
    override fun onPause() { adapter?.disableReaderMode(this); super.onPause() }
    override fun onTagDiscovered(tag: Tag) = model.nfc.onTag(tag)
}

@Composable private fun SpoolioTheme(content: @Composable () -> Unit) {
    val colors = lightColorScheme(primary = Color(0xFF286354), secondary = Color(0xFF7A5731), background = Color(0xFFF8F6F0), surface = Color(0xFFFFFCF5), error = Color(0xFF9B2C2C))
    MaterialTheme(colorScheme = colors, typography = Typography(), content = content)
}

@Composable fun SpoolioApp(model: MainViewModel, nfcAvailable: Boolean) {
    var custom by remember { mutableStateOf<CustomSeed?>(null) }
    var showCustom by remember { mutableStateOf(false) }
    Scaffold(
        topBar = { TopAppBar(title = { Column { Text("Spoolio", fontWeight = FontWeight.Bold); Text("Offline filament tag manager", style = MaterialTheme.typography.labelMedium) } }) },
        floatingActionButton = { ExtendedFloatingActionButton(onClick = { custom = CustomSeed(); showCustom = true }) { Text("Custom filament") } },
    ) { padding ->
        Column(Modifier.padding(padding).padding(horizontal = 16.dp).fillMaxSize()) {
            if (!nfcAvailable) Notice("NFC is unavailable on this device. Offline catalog remains usable.", true)
            model.error?.let { Notice(it, true) }
            OutlinedTextField(model.query, { model.query = it }, Modifier.fillMaxWidth().padding(top = 12.dp), label = { Text("Search brand, material, product, color, or package ID") }, singleLine = true, trailingIcon = { TextButton(onClick = model::search) { Text("Search") } })
            NfcPanel(model.nfc)
            when {
                model.loading -> Box(Modifier.fillMaxSize(), contentAlignment = Alignment.Center) { CircularProgressIndicator() }
                model.selected != null -> Detail(model, model.selected!!, { custom = model.seed(model.selected!!); showCustom = true }) { model.selected = null }
                else -> {
                    ReadResult(model.nfc.lastRead) { model.decodedSeed()?.let { custom = it; showCustom = true } }
                    CatalogList(model.recents, model.results, model::select)
                }
            }
        }
    }
    if (showCustom) CustomDialog(custom ?: CustomSeed(), onDismiss = { showCustom = false }, onSave = { values -> model.saveCustom(custom ?: CustomSeed(), values); showCustom = false })
}

@Composable private fun ReadResult(result: DecodeResult?, edit: () -> Unit) {
    when (result) {
        is DecodeResult.Supported -> Card(Modifier.fillMaxWidth().padding(top = 8.dp)) { Column(Modifier.padding(12.dp)) { Text("Supported OpenSpool tag read", fontWeight = FontWeight.Bold); Text("Fields were decoded without rewriting the tag."); TextButton(onClick = edit) { Text("Edit as a local record") } } }
        is DecodeResult.ReadOnly -> Notice("Read-only tag: ${result.reason}", false)
        is DecodeResult.Rejected -> Notice("Tag not editable: ${result.reason}", false)
        null -> Unit
    }
}

@Composable private fun CatalogList(recents: List<FilamentItem>, entries: List<FilamentItem>, select: (FilamentItem) -> Unit) {
    if (recents.isNotEmpty()) {
        Text("Recent", Modifier.padding(top = 12.dp), fontWeight = FontWeight.Bold)
        recents.take(5).forEach { item ->
            val e = item.entry
            TextButton(onClick = { select(item) }, modifier = Modifier.fillMaxWidth()) { Text((e.brand + " · " + e.product.ifBlank { e.material }) + " — " + e.colorName.ifBlank { "#" + e.colorHex }, modifier = Modifier.fillMaxWidth()) }
        }
    }
    Text("${entries.size} matches shown", Modifier.padding(vertical = 12.dp), style = MaterialTheme.typography.labelLarge)
    LazyColumn(verticalArrangement = Arrangement.spacedBy(8.dp), contentPadding = PaddingValues(bottom = 88.dp)) {
        items(entries, key = { it.entry.packageId }) { item ->
            val e = item.entry
            Card(Modifier.fillMaxWidth().clickable { select(item) }) {
                Row(Modifier.padding(14.dp), verticalAlignment = Alignment.CenterVertically) {
                    val color = runCatching { Color(android.graphics.Color.parseColor(e.colorHex)) }.getOrElse { Color.Gray }
                    Box(Modifier.size(42.dp).background(color, RoundedCornerShape(12.dp)).semantics { contentDescription = "${e.colorName.ifBlank { "Filament" }} color sample" })
                    Spacer(Modifier.width(12.dp))
                    Column(Modifier.weight(1f)) {
                        Text("${e.brand} · ${e.product.ifBlank { e.material }}", fontWeight = FontWeight.SemiBold)
                        Text("${e.material} — ${e.colorName.ifBlank { "#" + e.colorHex }}")
                        Text(packageSummary(e), style = MaterialTheme.typography.bodySmall)
                    }
                }
            }
        }
    }
}

@Composable private fun Detail(model: MainViewModel, item: FilamentItem, edit: () -> Unit, back: () -> Unit) {
    val e = item.entry
    val intentResult = remember(item, model.profile) { runCatching { model.intent(item) } }
    val intent = intentResult.getOrNull()
    Column(Modifier.verticalScroll(rememberScrollState()).padding(vertical = 12.dp), verticalArrangement = Arrangement.spacedBy(10.dp)) {
        TextButton(onClick = back) { Text("‹ Back to catalog") }
        Text("${e.brand} ${e.product.ifBlank { e.material }}", style = MaterialTheme.typography.headlineSmall, fontWeight = FontWeight.Bold)
        Text("${e.colorName.ifBlank { "#" + e.colorHex }} · ${e.material}")
        Info("Exact package", packageSummary(e)); Info("Nozzle", range(e.nozzleMinC, e.nozzleMaxC)); Info("Bed", range(e.bedMinC, e.bedMaxC)); Info("Barcode", e.gtin ?: "Missing in source")
        Info("Provenance", when (item.provenance) { Provenance.CATALOG -> "OFD ${e.sourceRevision} · catalog"; Provenance.CATALOG_EDITED -> "Locally edited from OFD ${e.sourceRevision}"; Provenance.CUSTOM -> "Local custom" })
        Text("Field sources: brand ${item.source("brand")}; material ${item.source("material")}; color ${item.source("colorHex")}", style = MaterialTheme.typography.bodySmall)
        OutlinedButton(onClick = edit, modifier = Modifier.fillMaxWidth()) { Text(if (item.provenance == Provenance.CATALOG) "Edit locally" else "Edit saved record") }
        Text("Tag compatibility", fontWeight = FontWeight.Bold)
        SingleChoiceSegmentedButtonRow(Modifier.fillMaxWidth()) {
            OpenSpoolProfile.entries.forEachIndexed { i, p -> SegmentedButton(selected = model.profile == p, onClick = { model.profile = p }, shape = SegmentedButtonDefaults.itemShape(i, 2), modifier = Modifier.heightIn(min = 48.dp)) { Text(if (p == OpenSpoolProfile.CANONICAL) "Canonical" else "PAXX") } }
        }
        intent?.let { Notice("NDEF payload ${it.payload.size} bytes. Not written in this profile: ${it.omittedFields.sorted().joinToString { fieldLabel(it) }}.", false) }
        intentResult.exceptionOrNull()?.message?.let { Notice("Complete missing or invalid fields before writing: $it", true) }
        Button(onClick = { model.arm(item) }, modifier = Modifier.fillMaxWidth(), enabled = intent != null) { Text("Prepare verified NFC write") }
        Spacer(Modifier.height(90.dp))
    }
}

@Composable private fun NfcPanel(nfc: NfcCoordinator) {
    val s = nfc.state
    if (s.phase != WritePhase.DRAFT) Card(Modifier.fillMaxWidth().padding(top = 8.dp), colors = CardDefaults.cardColors(containerColor = if (s.phase == WritePhase.VERIFIED) Color(0xFFDDEFE6) else Color(0xFFFFF1D8))) {
        Column(Modifier.padding(14.dp)) {
            Text(phaseLabel(s.phase), fontWeight = FontWeight.Bold); Text(s.detail)
            if (s.phase == WritePhase.NEEDS_OVERWRITE_CONSENT) Button(onClick = nfc::approveOverwrite) { Text("Approve overwrite for this tag") }
            if (s.phase !in setOf(WritePhase.VERIFIED, WritePhase.WRITE_OUTCOME_UNKNOWN, WritePhase.UNRESOLVED_ARCHIVED)) TextButton(onClick = nfc::cancel) { Text("Cancel before writing") }
            if (s.phase == WritePhase.WRITE_OUTCOME_UNKNOWN) Text("This unresolved operation remains recorded. Re-tap the same tag for read-only reconciliation.", style = MaterialTheme.typography.bodySmall)
            if (s.phase == WritePhase.WRITE_OUTCOME_UNKNOWN) OutlinedButton(onClick = nfc::archiveUnknown) { Text("Archive unresolved result; start another") }
            if (nfc.unresolvedArchiveCount > 0) Text("${nfc.unresolvedArchiveCount} unresolved write result(s) retained in local history.", style = MaterialTheme.typography.bodySmall)
        }
    }
}

@Composable private fun Info(label: String, value: String) { Row(Modifier.fillMaxWidth(), horizontalArrangement = Arrangement.spacedBy(12.dp)) { Text(label, Modifier.width(105.dp), fontWeight = FontWeight.SemiBold); Text(value, Modifier.weight(1f)) } }
@Composable private fun Notice(text: String, error: Boolean) { Surface(color = if (error) MaterialTheme.colorScheme.errorContainer else MaterialTheme.colorScheme.secondaryContainer, shape = RoundedCornerShape(10.dp)) { Text(text, Modifier.padding(12.dp)) } }
private fun range(a: Int?, b: Int?) = when { a == null && b == null -> "Missing in source"; a == b -> "$a °C"; else -> "${a ?: "?"}–${b ?: "?"} °C" }
private fun packageSummary(e: net.jamesjennison.spoolio.data.CatalogEntry) = e.diameterMm.ifBlank { "Diameter missing" } + (if (e.diameterMm.isNotBlank()) " mm" else "") + " · " + if (e.massG > 0) "${e.massG} g" else "Mass missing"

@Composable private fun CustomDialog(seed: CustomSeed, onDismiss: () -> Unit, onSave: (Map<String, String>) -> Unit) {
    val values = remember(seed) { mutableStateMapOf<String, String>().apply { putAll(seed.values()) } }
    val fields = listOf("brand" to "Brand", "material" to "Material", "product" to "Product (optional label)", "colorName" to "Color name (optional label)", "colorHex" to "Color hex", "diameter" to "Diameter mm", "mass" to "Mass g", "nozzleMin" to "Nozzle minimum °C", "nozzleMax" to "Nozzle maximum °C", "bedMin" to "Bed minimum °C", "bedMax" to "Bed maximum °C")
    AlertDialog(
        onDismissRequest = onDismiss, title = { Text(if (seed.id == null) "Custom filament" else "Edit filament locally") },
        text = { Column(Modifier.verticalScroll(rememberScrollState()), verticalArrangement = Arrangement.spacedBy(4.dp)) { Text("Blank optional or physical fields remain missing. Each changed field is marked Edited locally.", style = MaterialTheme.typography.bodySmall); fields.forEach { (key, label) -> OutlinedTextField(values[key].orEmpty(), { values[key] = it }, label = { Text(label) }, supportingText = seed.sources[key]?.takeIf(String::isNotBlank)?.let { { Text("Source: $it") } }, singleLine = true) } } },
        confirmButton = { Button(onClick = { onSave(values.toMap()) }) { Text("Save locally") } }, dismissButton = { TextButton(onClick = onDismiss) { Text("Cancel") } },
    )
}

private fun fieldLabel(value: String) = mapOf("product" to "product label", "diameter" to "diameter", "mass" to "mass", "nozzleMin" to "nozzle minimum", "nozzleMax" to "nozzle maximum", "bedMin" to "bed minimum", "bedMax" to "bed maximum", "additionalColors" to "additional colors", "packageId" to "package identifier", "gtin" to "barcode", "sku" to "article number", "provenance" to "field provenance")[value] ?: value
private fun phaseLabel(phase: WritePhase) = when (phase) { WritePhase.AWAITING_TAG -> "Ready for tag"; WritePhase.INSPECTING -> "Inspecting tag"; WritePhase.NEEDS_OVERWRITE_CONSENT -> "Overwrite approval needed"; WritePhase.WRITING -> "Writing — keep tag in place"; WritePhase.VERIFYING -> "Verifying fresh read"; WritePhase.VERIFIED -> "Write verified"; WritePhase.CANCELLED -> "Cancelled before writing"; WritePhase.REJECTED -> "Tag rejected"; WritePhase.FAILED_BEFORE_WRITE -> "Write not attempted"; WritePhase.WRITE_OUTCOME_UNKNOWN -> "Write outcome unknown"; WritePhase.UNRESOLVED_ARCHIVED -> "Unresolved result archived"; WritePhase.DRAFT -> "Draft" }

package net.jamesjennison.spoolio

import android.app.Application
import androidx.compose.runtime.*
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.flow.collectLatest
import kotlinx.coroutines.launch
import kotlinx.coroutines.withContext
import net.jamesjennison.spoolio.core.*
import net.jamesjennison.spoolio.data.*
import java.util.UUID

private val EDITABLE_FIELDS = listOf("brand", "material", "product", "colorName", "colorHex", "diameter", "mass", "nozzleMin", "nozzleMax", "bedMin", "bedMax")
data class FilamentItem(val entry: CatalogEntry, val provenance: Provenance, val sources: Map<String, String>, val originalPackageId: String? = null) { fun source(field: String) = sources[field].orEmpty() }
data class CustomSeed(
    val id: String? = null, val originalPackageId: String? = null,
    val variantId: String = "", val productId: String = "", val gtin: String? = null, val articleNumber: String? = null, val additionalColorHexes: String = "",
    val brand: String = "", val material: String = "", val product: String = "", val color: String = "",
    val hex: String = "", val diameter: String = "", val mass: String = "",
    val nozzleMin: String = "", val nozzleMax: String = "", val bedMin: String = "", val bedMax: String = "",
    val sourceRevision: String = "user", val provenance: Provenance = Provenance.CUSTOM,
    val sources: Map<String, String> = emptyMap(), val originalValues: Map<String, String> = emptyMap(),
) {
    fun values() = mapOf("brand" to brand, "material" to material, "product" to product, "colorName" to color, "colorHex" to hex, "diameter" to diameter, "mass" to mass, "nozzleMin" to nozzleMin, "nozzleMax" to nozzleMax, "bedMin" to bedMin, "bedMax" to bedMax)
}

class MainViewModel(app: Application) : AndroidViewModel(app) {
    private val store = (app as SpoolioApplication).data
    val nfc = NfcCoordinator(app)
    var loading by mutableStateOf(true); private set
    var query by mutableStateOf("")
    var results by mutableStateOf<List<FilamentItem>>(emptyList()); private set
    var recents by mutableStateOf<List<FilamentItem>>(emptyList()); private set
    var selected by mutableStateOf<FilamentItem?>(null)
    var error by mutableStateOf<String?>(null); private set
    var profile by mutableStateOf(OpenSpoolProfile.CANONICAL)
    private var customItems: List<FilamentItem> = emptyList()
    private var catalogItems: List<FilamentItem> = emptyList()

    init {
        viewModelScope.launch {
            runCatching { withContext(Dispatchers.IO) { store.ensureCatalog(); store.catalog.catalog().browse().map(CatalogEntry::asCatalogItem) } }
                .onSuccess { catalogItems = it; refreshVisible(); loading = false }
                .onFailure { error = it.message; loading = false }
            store.user.user().recents().collectLatest { saved ->
                recents = saved.mapNotNull { recent ->
                    decodeSnapshot(recent.snapshotJson) ?: restoreLegacyRecent(recent)
                }
            }
        }
        viewModelScope.launch { store.user.user().customs().collectLatest { customItems = it.map(CustomRecord::asItem); refreshVisible() } }
    }

    private suspend fun restoreLegacyRecent(recent: Recent): FilamentItem? = runCatching {
        val obj = StrictJson(16 * 1024).parse(recent.snapshotJson.encodeToByteArray()) as JsonValue.Obj
        val id = obj.string("package_id") ?: return null
        val revision = obj.string("source_revision") ?: return null
        val entry = store.catalog.catalog().byId(id) ?: return null
        // v1 retained a short pinned revision; never substitute a different generation.
        if (revision.length < 8 || !entry.sourceRevision.startsWith(revision)) return null
        val item = entry.asCatalogItem()
        store.user.user().recent(recent.copy(snapshotJson = encodeSnapshot(item)))
        item
    }.getOrNull()

    private fun refreshVisible() { if (query.isBlank()) results = customItems + catalogItems }
    fun search() {
        val q = query.trim()
        if (q.length > 120) { error = "Search is limited to 120 characters"; return }
        viewModelScope.launch {
            runCatching {
                withContext(Dispatchers.IO) {
                    val dao = store.catalog.catalog()
                    val catalog = if (q.isBlank()) dao.browse() else {
                        val fts = dao.search(q.split(Regex("\\s+")).take(8).joinToString(" ") { "\"${it.replace("\"", "\"\"")}\"*" })
                        (listOfNotNull(dao.byId(q)) + fts).distinctBy(CatalogEntry::packageId)
                    }
                    val local = if (q.isBlank()) customItems else customItems.filter { item -> listOf(item.entry.packageId, item.entry.brand, item.entry.material, item.entry.product, item.entry.colorName).any { it.contains(q, true) } }
                    local + catalog.map(CatalogEntry::asCatalogItem)
                }
            }.onSuccess { results = it; error = null }.onFailure { error = "Search could not be completed" }
        }
    }

    fun select(item: FilamentItem) {
        selected = item
        viewModelScope.launch(Dispatchers.IO) { store.user.user().recent(Recent(item.entry.packageId, item.provenance.name, encodeSnapshot(item), System.currentTimeMillis())) }
    }
    fun intent(item: FilamentItem): OpenSpoolIntent = OpenSpoolCodec.encode(item.toRecord(), profile)
    fun arm(item: FilamentItem) { runCatching { nfc.arm(intent(item)) }.onFailure { error = it.message } }

    fun seed(item: FilamentItem): CustomSeed {
        val e = item.entry
        val values = item.values()
        return CustomSeed(
            id = if (item.provenance == Provenance.CATALOG) "edited:" + e.packageId else e.packageId,
            originalPackageId = item.originalPackageId ?: e.packageId,
            variantId = e.variantId, productId = e.productId, gtin = e.gtin, articleNumber = e.sku, additionalColorHexes = e.additionalColorHexes,
            brand = e.brand, material = e.material, product = e.product, color = e.colorName, hex = e.colorHex,
            diameter = e.diameterMm, mass = e.massG.takeIf { it > 0 }?.toString().orEmpty(),
            nozzleMin = e.nozzleMinC?.toString().orEmpty(), nozzleMax = e.nozzleMaxC?.toString().orEmpty(),
            bedMin = e.bedMinC?.toString().orEmpty(), bedMax = e.bedMaxC?.toString().orEmpty(),
            sourceRevision = e.sourceRevision,
            provenance = if (item.provenance == Provenance.CATALOG) Provenance.CATALOG_EDITED else item.provenance,
            sources = item.sources, originalValues = values,
        )
    }

    fun saveCustom(seed: CustomSeed, values: Map<String, String>) {
        val normalizedHex = runCatching { normalizeHex(values["colorHex"].orEmpty()) }.getOrElse { error = it.message; return }
        val normalized = values + ("colorHex" to normalizedHex)
        fun optionalInt(key: String): Int? {
            val raw = normalized[key].orEmpty()
            if (raw.isBlank()) return null
            return raw.toIntOrNull() ?: throw ValidationException("$key must be a whole number")
        }
        val mass = runCatching { optionalInt("mass") }.getOrElse { error = it.message; return }
        val diameter = normalized["diameter"].orEmpty()
        val temperatures = runCatching { listOf("nozzleMin", "nozzleMax", "bedMin", "bedMax").associateWith(::optionalInt) }.getOrElse { error = it.message; return }
        fun temp(key: String) = temperatures[key]
        val record = FilamentRecord(
            seed.id ?: UUID.randomUUID().toString(), seed.variantId, seed.productId,
            FieldValue(normalized["brand"].orEmpty(), "User"), FieldValue(normalized["material"].orEmpty(), "User"),
            FieldValue(normalized["product"].orEmpty(), "User"), FieldValue(normalized["colorName"].orEmpty(), "User"),
            FieldValue(normalizedHex, "User"), FieldValue(diameter, "User"), FieldValue(mass ?: 0, "User"),
            temp("nozzleMin")?.let { FieldValue(it, "User") }, temp("nozzleMax")?.let { FieldValue(it, "User") },
            temp("bedMin")?.let { FieldValue(it, "User") }, temp("bedMax")?.let { FieldValue(it, "User") },
            seed.gtin, seed.articleNumber, seed.sourceRevision, seed.provenance, seed.additionalColorHexes.split(',').filter(String::isNotBlank),
        )
        runCatching { validateEditable(record, mass) }.onFailure { error = it.message; return }
        val sources = EDITABLE_FIELDS.associateWith { key ->
            when {
                normalized[key].orEmpty().isBlank() -> seed.sources[key].orEmpty()
                seed.originalValues.isNotEmpty() && seed.originalValues[key] != normalized[key].orEmpty() -> "Edited locally"
                seed.sources[key].isNullOrBlank() -> "User"
                else -> seed.sources.getValue(key)
            }
        }
        val saved = CustomRecord(
            record.packageId, seed.originalPackageId, seed.variantId, seed.productId, record.brand.value, record.material.value, record.product.value, record.colorName.value,
            normalizedHex, diameter, mass ?: 0, record.nozzleMinC?.value, record.nozzleMaxC?.value, record.bedMinC?.value, record.bedMaxC?.value,
            seed.gtin, seed.articleNumber, seed.additionalColorHexes,
            seed.sourceRevision, seed.provenance.name,
            sources.getValue("brand"), sources.getValue("material"), sources.getValue("product"), sources.getValue("colorName"), sources.getValue("colorHex"),
            sources.getValue("diameter"), sources.getValue("mass"), record.nozzleMinC?.let { sources["nozzleMin"] }, record.nozzleMaxC?.let { sources["nozzleMax"] },
            record.bedMinC?.let { sources["bedMin"] }, record.bedMaxC?.let { sources["bedMax"] }, System.currentTimeMillis(),
        )
        viewModelScope.launch {
            withContext(Dispatchers.IO) { store.user.user().save(saved) }
            selected = saved.asItem(); error = null
        }
    }

    fun decodedSeed(): CustomSeed? {
        val values = (nfc.lastRead as? DecodeResult.Supported)?.values ?: return null
        fun text(key: String) = (values[key] as? JsonValue.Str)?.value.orEmpty()
        fun number(key: String) = when (val value = values[key]) { is JsonValue.Num -> value.lexical; is JsonValue.Str -> value.value; else -> "" }
        val fields = mapOf(
            "brand" to text("brand"), "material" to text("type"), "product" to text("subtype"), "colorName" to "",
            "colorHex" to text("color_hex"), "diameter" to number("diameter"), "mass" to number("weight"),
            "nozzleMin" to number("min_temp"), "nozzleMax" to number("max_temp"), "bedMin" to number("bed_min_temp"), "bedMax" to number("bed_max_temp"),
        )
        val additionalColors = (values["additional_color_hexes"] as? JsonValue.Arr)?.values?.mapNotNull { (it as? JsonValue.Str)?.value }?.joinToString(",").orEmpty()
        return CustomSeed(
            additionalColorHexes = additionalColors,
            brand = fields.getValue("brand"), material = fields.getValue("material"), product = fields.getValue("product"), color = "",
            hex = fields.getValue("colorHex"), diameter = fields.getValue("diameter"), mass = fields.getValue("mass"),
            nozzleMin = fields.getValue("nozzleMin"), nozzleMax = fields.getValue("nozzleMax"), bedMin = fields.getValue("bedMin"), bedMax = fields.getValue("bedMax"),
            sources = fields.filterValues(String::isNotBlank).mapValues { "OpenSpool tag" }, originalValues = fields,
        )
    }
    override fun onCleared() { nfc.shutdown(); super.onCleared() }
}

private fun validateEditable(record: FilamentRecord, mass: Int?) {
    if (record.brand.value.isBlank() || record.material.value.isBlank()) throw ValidationException("Brand and material are required")
    listOf(record.brand.value, record.material.value, record.product.value, record.colorName.value).forEach {
        if (it.length > 200 || it.any(Char::isISOControl)) throw ValidationException("Text fields must be at most 200 printable characters")
    }
    normalizeHex(record.colorHex.value)
    if (record.diameterMm.value.isNotBlank()) {
        val diameter = record.diameterMm.value.toBigDecimalOrNull() ?: throw ValidationException("Diameter must be decimal millimetres")
        if (diameter <= java.math.BigDecimal.ZERO || diameter > java.math.BigDecimal.TEN) throw ValidationException("Diameter must be in millimetres; legacy 175 is not valid")
    }
    if (mass != null && mass !in 1..100_000) throw ValidationException("Nominal mass is outside the supported range")
    fun range(name: String, min: FieldValue<Int>?, max: FieldValue<Int>?) {
        if ((min?.value ?: 0) !in 0..500 || (max?.value ?: 0) !in 0..500 || (min != null && max != null && min.value > max.value)) throw ValidationException("$name temperature range is invalid")
    }
    range("Nozzle", record.nozzleMinC, record.nozzleMaxC); range("Bed", record.bedMinC, record.bedMaxC)
}

private fun CatalogEntry.asCatalogItem(): FilamentItem {
    val source = "OFD $sourceRevision"
    return FilamentItem(this, Provenance.CATALOG, EDITABLE_FIELDS.associateWith { source })
}
private fun CustomRecord.asItem(): FilamentItem {
    val entry = CatalogEntry(id, variantId, productId, brand, material, product, colorName, colorHex, diameterMm, massG, nozzleMinC, nozzleMaxC, bedMinC, bedMaxC, gtin, articleNumber, sourceRevision, additionalColorHexes)
    val sources = mapOf("brand" to brandSource, "material" to materialSource, "product" to productSource, "colorName" to colorNameSource, "colorHex" to colorHexSource, "diameter" to diameterSource, "mass" to massSource, "nozzleMin" to nozzleMinSource.orEmpty(), "nozzleMax" to nozzleMaxSource.orEmpty(), "bedMin" to bedMinSource.orEmpty(), "bedMax" to bedMaxSource.orEmpty())
    return FilamentItem(entry, runCatching { Provenance.valueOf(provenance) }.getOrDefault(Provenance.CUSTOM), sources, originalPackageId)
}
private fun FilamentItem.values() = mapOf(
    "brand" to entry.brand, "material" to entry.material, "product" to entry.product, "colorName" to entry.colorName,
    "colorHex" to entry.colorHex, "diameter" to entry.diameterMm, "mass" to entry.massG.takeIf { it > 0 }?.toString().orEmpty(),
    "nozzleMin" to entry.nozzleMinC?.toString().orEmpty(), "nozzleMax" to entry.nozzleMaxC?.toString().orEmpty(),
    "bedMin" to entry.bedMinC?.toString().orEmpty(), "bedMax" to entry.bedMaxC?.toString().orEmpty(),
)
private fun FilamentItem.toRecord(): FilamentRecord {
    val e = entry
    fun text(key: String, value: String) = FieldValue(value, source(key))
    fun number(key: String, value: Int?) = value?.let { FieldValue(it, source(key)) }
    return FilamentRecord(e.packageId, e.variantId, e.productId, text("brand", e.brand), text("material", e.material), text("product", e.product), text("colorName", e.colorName), text("colorHex", e.colorHex), text("diameter", e.diameterMm), FieldValue(e.massG, source("mass")), number("nozzleMin", e.nozzleMinC), number("nozzleMax", e.nozzleMaxC), number("bedMin", e.bedMinC), number("bedMax", e.bedMaxC), e.gtin, e.sku, e.sourceRevision, provenance, e.additionalColorHexes.split(',').filter(String::isNotBlank))
}
internal fun encodeSnapshot(item: FilamentItem): String {
    val values = item.values().toMutableMap()
    values["packageId"] = item.entry.packageId; values["sourceRevision"] = item.entry.sourceRevision; values["provenance"] = item.provenance.name
    values["originalPackageId"] = item.originalPackageId.orEmpty()
    values["variantId"] = item.entry.variantId; values["productId"] = item.entry.productId
    values["gtin"] = item.entry.gtin.orEmpty(); values["articleNumber"] = item.entry.sku.orEmpty(); values["additionalColorHexes"] = item.entry.additionalColorHexes
    item.sources.forEach { (key, value) -> values["source_$key"] = value }
    return encodeJsonObject(values).decodeToString()
}
internal fun decodeSnapshot(json: String): FilamentItem? = runCatching {
    val obj = StrictJson(16 * 1024).parse(json.encodeToByteArray()) as JsonValue.Obj
    require(!obj.string("packageId").isNullOrBlank()) { "Legacy or invalid recent snapshot" }
    fun text(key: String) = obj.string(key).orEmpty()
    fun int(key: String) = text(key).toIntOrNull()
    val entry = CatalogEntry(text("packageId"), text("variantId"), text("productId"), text("brand"), text("material"), text("product"), text("colorName"), text("colorHex"), text("diameter"), int("mass") ?: 0, int("nozzleMin"), int("nozzleMax"), int("bedMin"), int("bedMax"), text("gtin").ifBlank { null }, text("articleNumber").ifBlank { null }, text("sourceRevision"), text("additionalColorHexes"))
    FilamentItem(entry, runCatching { Provenance.valueOf(text("provenance")) }.getOrDefault(Provenance.CUSTOM), EDITABLE_FIELDS.associateWith { text("source_$it") }, text("originalPackageId").ifBlank { null })
}.getOrNull()

package net.jamesjennison.spoolio

import android.content.Context
import android.nfc.*
import android.nfc.tech.Ndef
import android.os.Handler
import android.os.Looper
import android.util.Base64
import androidx.compose.runtime.*
import net.jamesjennison.spoolio.core.*
import java.util.concurrent.Executors

class NfcCoordinator(context:Context) {
    private val machine=WriteStateMachine(); private val io=Executors.newSingleThreadExecutor(); private val main=Handler(Looper.getMainLooper())
    private val journal=WriteJournal(context)
    var state by mutableStateOf(machine.state); private set
    var lastRead by mutableStateOf<DecodeResult?>(null); private set
    var unresolvedArchiveCount by mutableIntStateOf(journal.archiveCount()); private set
    init { journal.load()?.let{machine.restoreUnknown(it.uid,it.payload);state=machine.state} }
    fun arm(intent:OpenSpoolIntent)=dispatch{machine.arm(intent)}
    fun approveOverwrite()=dispatch{machine.approveOverwrite()}
    fun cancel()=dispatch{machine.cancel();persistOrClear()}
    fun archiveUnknown()=dispatch{val s=machine.state;val uid=s.uid?:error("No unresolved tag");val payload=journal.activePayload()?:error("No unresolved payload");check(journal.archive(uid,payload)){"Could not archive unresolved write"};machine.archiveUnknown();journal.clear();main.post{unresolvedArchiveCount=journal.archiveCount()}}
    fun shutdown(){io.shutdown()}
    fun onTag(tag:Tag){ io.execute { handle(tag) } }
    private fun dispatch(block:()->Unit){io.execute{runCatching(block).onFailure{e->main.post{state=state.copy(detail=e.message?:"Operation rejected")}};publish()}}
    private fun publish(){val next=machine.state;main.post{state=next}}
    private fun persistOrClear(){val s=machine.state;when(s.phase){WritePhase.WRITING,WritePhase.VERIFYING,WritePhase.WRITE_OUTCOME_UNKNOWN->{val uid=s.uid;val payload=s.intent?.payload;if(uid!=null&&payload!=null)journal.save(uid,payload)}WritePhase.VERIFIED->journal.clear();else->Unit}}
    private fun awaitingWrite()=machine.state.phase in setOf(WritePhase.AWAITING_TAG,WritePhase.INSPECTING,WritePhase.NEEDS_OVERWRITE_CONSENT)
    private fun handle(tag:Tag){
        val ndef=Ndef.get(tag) ?: run {if(awaitingWrite()){machine.rejectBeforeWrite("Unsupported or unformatted tag. Automatic formatting is disabled.");publish()}else main.post{lastRead=DecodeResult.Rejected("Unsupported or unformatted tag. Automatic formatting is disabled.")};return}
        try {
            ndef.connect()
            val current=ndef.ndefMessage // active RF read; never cachedNdefMessage
            val records=current?.records?.map{TagRecord(it.tnf.toInt(),it.type.toString(Charsets.US_ASCII),it.payload)}?:emptyList()
            val snapshot=TagSnapshot(tag.id.copyOf(),ndef.isWritable,ndef.maxSize,records)
            if(machine.state.phase==WritePhase.VERIFYING||machine.state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN){
                machine.reconciled(snapshot);persistOrClear();main.post{lastRead=decodeSingleOpenSpool(current)};publish();return
            }
            if(!awaitingWrite()){main.post{lastRead=decodeSingleOpenSpool(current)};return}
            val intent=machine.state.intent ?: return
            val message=NdefMessage(arrayOf(NdefRecord.createMime(OpenSpoolCodec.MIME,intent.payload)))
            val existingOpenSpool=current?.records?.filter{it.tnf==NdefRecord.TNF_MIME_MEDIA&&it.type.toString(Charsets.US_ASCII)==OpenSpoolCodec.MIME}.orEmpty()
            if(records.size>1||records.isNotEmpty()&&existingOpenSpool.size!=1){machine.rejectBeforeWrite("Existing tag content is ambiguous and will not be overwritten");publish();return}
            if(existingOpenSpool.size>1){machine.rejectBeforeWrite("Multiple OpenSpool records are ambiguous and will not be overwritten");publish();return}
            val unsupported=existingOpenSpool.map{OpenSpoolCodec.decode(it.payload)}.firstOrNull{it !is DecodeResult.Supported}
            if(unsupported!=null){val reason=when(unsupported){is DecodeResult.ReadOnly->unsupported.reason;is DecodeResult.Rejected->unsupported.reason;else->"Unsupported OpenSpool profile"};machine.rejectBeforeWrite("Existing OpenSpool content is read-only: $reason");publish();return}
            machine.inspected(snapshot,message.toByteArray().size);publish()
            if(machine.state.phase!=WritePhase.WRITING)return
            val writeUid=machine.state.uid;val writePayload=machine.state.intent?.payload
            if(writeUid==null||writePayload==null||!journal.save(writeUid,writePayload)){machine.writeFailedBeforeCall("Could not durably journal the write; no write was attempted");publish();return}
            try { ndef.writeNdefMessage(message) } catch(e:Exception){ machine.writeInterrupted("Write did not complete: ${e.javaClass.simpleName}");publish();return }
            machine.writeReturned();persistOrClear();publish()
            // This is an uncached RF read after write. Any loss leaves UNKNOWN.
            val fresh=ndef.ndefMessage
            val freshRecords=fresh?.records?.map{TagRecord(it.tnf.toInt(),it.type.toString(Charsets.US_ASCII),it.payload)}?:emptyList()
            machine.reconciled(TagSnapshot(tag.id.copyOf(),ndef.isWritable,ndef.maxSize,freshRecords));persistOrClear();main.post{lastRead=decodeSingleOpenSpool(fresh)};publish()
        } catch(e:Exception){
            if(machine.state.phase==WritePhase.WRITING||machine.state.phase==WritePhase.VERIFYING)machine.writeInterrupted("Tag connection lost")
            else if(machine.state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN)machine.unknownReadFailed("NFC reconciliation read failed: ${e.javaClass.simpleName}")
            else if(awaitingWrite())machine.rejectBeforeWrite("NFC read failed: ${e.javaClass.simpleName}") else main.post{lastRead=DecodeResult.Rejected("NFC read failed: ${e.javaClass.simpleName}")}
            persistOrClear()
            publish()
        } finally { runCatching{ndef.close()} }
    }
    private fun decodeSingleOpenSpool(message:NdefMessage?):DecodeResult {val records=message?.records?:emptyArray();if(records.size!=1)return DecodeResult.Rejected("Expected exactly one OpenSpool NDEF record");val record=records.single();if(record.tnf!=NdefRecord.TNF_MIME_MEDIA||record.type.toString(Charsets.US_ASCII)!=OpenSpoolCodec.MIME)return DecodeResult.Rejected("No OpenSpool MIME record found");return OpenSpoolCodec.decode(record.payload)}
}

internal class WriteJournal(context:Context){
    data class Entry(val uid:ByteArray,val payload:ByteArray)
    private val prefs=context.getSharedPreferences("nfc-write-journal",Context.MODE_PRIVATE)
    fun save(uid:ByteArray,payload:ByteArray):Boolean=prefs.edit().putInt("version",1).putString("uid",Base64.encodeToString(uid,Base64.NO_WRAP)).putString("payload",Base64.encodeToString(payload,Base64.NO_WRAP)).commit()
    fun load():Entry?=runCatching{if(prefs.getInt("version",0)!=1)return null;val uid=Base64.decode(prefs.getString("uid",null)?:return null,Base64.DEFAULT);val payload=Base64.decode(prefs.getString("payload",null)?:return null,Base64.DEFAULT);if(uid.isEmpty()||payload.isEmpty())return null;Entry(uid,payload)}.getOrNull()
    fun activePayload():ByteArray?=load()?.payload
    fun archiveCount():Int=prefs.getInt("archive_count",0)
    fun archive(uid:ByteArray,payload:ByteArray):Boolean{val count=prefs.getInt("archive_count",0);check(count < Int.MAX_VALUE){"Unresolved archive capacity reached"};val slot=count;return prefs.edit().putInt("archive_count",count+1).putString("archive_$slot",System.currentTimeMillis().toString()+":"+Base64.encodeToString(uid,Base64.NO_WRAP)+":"+Base64.encodeToString(payload,Base64.NO_WRAP)).commit()}
    fun clear():Boolean=prefs.edit().remove("version").remove("uid").remove("payload").commit()
}

