package net.jamesjennison.spoolio.core

import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.StandardCopyOption
import java.security.MessageDigest

/** Installs validated immutable catalog artifacts while retaining the previous good generation. */
class CatalogGenerationStore(private val root: Path) {
    data class Active(val generation:String,val artifact:Path)
    fun active():Active? {
        val pointer=root.resolve("active"); if(!Files.isRegularFile(pointer)) return null
        val id=Files.readString(pointer).trim(); if(!id.matches(Regex("[a-zA-Z0-9._-]{1,80}"))) return null
        val artifact=root.resolve("generations").resolve(id).resolve("catalog.asset")
        return if(Files.isRegularFile(artifact)) Active(id,artifact) else null
    }
    fun install(generation:String,bytes:ByteArray,expectedSha256:String,validate:(Path)->Boolean):Active {
        require(generation.matches(Regex("[a-zA-Z0-9._-]{1,80}")))
        Files.createDirectories(root.resolve("generations")); val staging=Files.createTempDirectory(root,"stage-")
        try {
            val artifact=staging.resolve("catalog.asset"); Files.write(artifact,bytes)
            val actual=MessageDigest.getInstance("SHA-256").digest(bytes).joinToString(""){"%02x".format(it)}
            require(actual==expectedSha256.lowercase()) { "Catalog digest mismatch" }
            require(validate(artifact)) { "Catalog validation failed" }
            val destination=root.resolve("generations").resolve(generation)
            if(!Files.exists(destination)) Files.move(staging,destination,StandardCopyOption.ATOMIC_MOVE)
            val pointerTemp=Files.createTempFile(root,"active-",".tmp"); Files.writeString(pointerTemp,"$generation\n")
            Files.move(pointerTemp,root.resolve("active"),StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING)
            return active() ?: error("Installed generation unavailable")
        } finally { if(Files.exists(staging)) Files.walk(staging).sorted(Comparator.reverseOrder()).forEach { Files.deleteIfExists(it) } }
    }
}

package net.jamesjennison.spoolio.core

enum class Provenance { CATALOG, CATALOG_EDITED, CUSTOM }

data class FieldValue<T>(val value: T, val source: String)

data class FilamentRecord(
    val packageId: String,
    val variantId: String?,
    val productId: String?,
    val brand: FieldValue<String>,
    val material: FieldValue<String>,
    val product: FieldValue<String>,
    val colorName: FieldValue<String>,
    val colorHex: FieldValue<String>,
    val diameterMm: FieldValue<String>,
    val nominalMassG: FieldValue<Int>,
    val nozzleMinC: FieldValue<Int>?,
    val nozzleMaxC: FieldValue<Int>?,
    val bedMinC: FieldValue<Int>?,
    val bedMaxC: FieldValue<Int>?,
    val gtin: String? = null,
    val sku: String? = null,
    val sourceRevision: String,
    val provenance: Provenance,
    val additionalColors: List<String> = emptyList(),
)

enum class OpenSpoolProfile { CANONICAL, PAXX }

/** A write intent whose byte content cannot be changed after user review. */
class OpenSpoolIntent(
    record: FilamentRecord,
    val profile: OpenSpoolProfile,
    payload: ByteArray,
    omittedFields: Set<String>,
) {
    val record: FilamentRecord = record.copy(additionalColors = record.additionalColors.toList())
    private val frozenPayload = payload.copyOf()
    val payload: ByteArray get() = frozenPayload.copyOf()
    val omittedFields: Set<String> = omittedFields.toSet()

    internal fun payloadUnsafe(): ByteArray = frozenPayload
    override fun equals(other: Any?) = other is OpenSpoolIntent && record == other.record && profile == other.profile && frozenPayload.contentEquals(other.frozenPayload) && omittedFields == other.omittedFields
    override fun hashCode() = 31 * (31 * (31 * record.hashCode() + profile.hashCode()) + frozenPayload.contentHashCode()) + omittedFields.hashCode()
}

sealed interface DecodeResult {
    data class Supported(val values: Map<String, JsonValue>, val raw: ByteArray) : DecodeResult
    data class ReadOnly(val reason: String, val raw: ByteArray) : DecodeResult
    data class Rejected(val reason: String) : DecodeResult
}

class ValidationException(message: String) : IllegalArgumentException(message)

fun normalizeHex(input: String): String {
    val value = input.removePrefix("#").uppercase()
    if (!value.matches(Regex("[0-9A-F]{6}"))) throw ValidationException("Color must be exactly six hexadecimal digits")
    return value
}

fun validateRecord(record: FilamentRecord) {
    if (record.brand.value.isBlank() || record.material.value.isBlank()) throw ValidationException("Brand and material are required")
    listOf(record.brand.value, record.material.value, record.product.value, record.colorName.value).forEach {
        if (it.length > 200 || it.any(Char::isISOControl)) throw ValidationException("Text fields must be at most 200 printable characters")
    }
    normalizeHex(record.colorHex.value)
    val diameter = record.diameterMm.value.toBigDecimalOrNull() ?: throw ValidationException("Diameter must be decimal millimetres")
    if (diameter <= java.math.BigDecimal.ZERO || diameter > java.math.BigDecimal("10")) throw ValidationException("Diameter must be in millimetres; legacy 175 is not valid")
    if (record.nominalMassG.value <= 0 || record.nominalMassG.value > 100_000) throw ValidationException("Nominal mass is outside the supported range")
    fun range(name: String, min: FieldValue<Int>?, max: FieldValue<Int>?) {
        if ((min?.value ?: 0) < 0 || (max?.value ?: 0) < 0) throw ValidationException("$name temperatures cannot be negative")
        if (min != null && max != null && min.value > max.value) throw ValidationException("$name temperature range is inverted")
        if ((min?.value ?: 0) > 500 || (max?.value ?: 0) > 500) throw ValidationException("$name temperature exceeds 500 C")
    }
    range("Nozzle", record.nozzleMinC, record.nozzleMaxC)
    range("Bed", record.bedMinC, record.bedMaxC)
    if (record.additionalColors.size > 4) throw ValidationException("OpenSpool supports at most four additional colors; choose which colors to export")
    record.additionalColors.forEach(::normalizeHex)
}

package net.jamesjennison.spoolio.core

object OpenSpoolCodec {
    const val MIME = "application/json"
    private val canonical = setOf("protocol","version","type","color_hex","brand","min_temp","max_temp")
    private val paxx = canonical + setOf("subtype","bed_min_temp","bed_max_temp","diameter","weight","additional_color_hexes")

    fun encode(record: FilamentRecord, profile: OpenSpoolProfile): OpenSpoolIntent {
        validateRecord(record)
        val fields = linkedMapOf<String,Any>("protocol" to "openspool", "version" to "1.0", "type" to record.material.value, "color_hex" to normalizeHex(record.colorHex.value), "brand" to record.brand.value)
        record.nozzleMinC?.let { fields["min_temp"] = it.value.toString() }
        record.nozzleMaxC?.let { fields["max_temp"] = it.value.toString() }
        if(profile == OpenSpoolProfile.PAXX) {
            if(record.product.value.isNotBlank()) fields["subtype"] = record.product.value
            record.bedMinC?.let { fields["bed_min_temp"] = it.value.toString() }
            record.bedMaxC?.let { fields["bed_max_temp"] = it.value.toString() }
            fields["diameter"] = record.diameterMm.value.toBigDecimal().stripTrailingZeros().toPlainString()
            fields["weight"] = record.nominalMassG.value
            if(record.additionalColors.isNotEmpty()) fields["additional_color_hexes"] = record.additionalColors.map(::normalizeHex)
        }
        val mapping = linkedMapOf("brand" to "brand","material" to "type","product" to "subtype","color" to "color_hex","diameter" to "diameter","mass" to "weight","nozzleMin" to "min_temp","nozzleMax" to "max_temp","bedMin" to "bed_min_temp","bedMax" to "bed_max_temp","additionalColors" to "additional_color_hexes","packageId" to null,"gtin" to null,"sku" to null,"provenance" to null)
        val omitted = mapping.filterValues { it==null||it !in fields }.keys
        return OpenSpoolIntent(record, profile, encodeJsonObject(fields), omitted)
    }

    fun decode(payload: ByteArray): DecodeResult {
      return try {
        val root = StrictJson().parse(payload) as? JsonValue.Obj ?: return DecodeResult.Rejected("OpenSpool payload must be an object")
        if(root.string("protocol") != "openspool") return DecodeResult.Rejected("Not an OpenSpool payload")
        val version=root.string("version") ?: return DecodeResult.Rejected("OpenSpool version must be a string")
        if(version != "1.0") return DecodeResult.ReadOnly("Unsupported OpenSpool version", payload.copyOf())
        val known = paxx + "alpha"
        if(root.values.keys.any { it !in known }) return DecodeResult.ReadOnly("Unknown fields must be preserved read-only", payload.copyOf())
        if("alpha" in root.values) return DecodeResult.ReadOnly("Alpha cannot yet be edited without verified lossless semantics",payload.copyOf())
        fun requiredText(key:String):String {
            val value=root.values[key] as? JsonValue.Str ?: throw ValidationException("$key must be a string")
            if(value.value.isBlank() || value.value.length>200 || value.value.any(Char::isISOControl)) throw ValidationException("$key is empty or invalid")
            return value.value
        }
        requiredText("type"); normalizeHex(requiredText("color_hex")); requiredText("brand")
        if("subtype" in root.values) requiredText("subtype")
        if("diameter" in root.values) {
            val raw=requiredText("diameter"); val diameter=raw.toBigDecimalOrNull() ?: throw ValidationException("diameter must be a decimal-millimetre string")
            if(diameter<=java.math.BigDecimal.ZERO||diameter>java.math.BigDecimal.TEN) throw ValidationException("diameter must be decimal millimetres; legacy 175 is invalid")
        }
        fun temp(key:String):Int? {
            if(key !in root.values)return null
            val raw=(root.values[key] as? JsonValue.Str)?.value ?: throw ValidationException("$key must be an integer string")
            if(!raw.matches(Regex("(?:0|[1-9][0-9]{0,2})"))) throw ValidationException("$key must be an integer from 0 to 500")
            return raw.toInt().also{if(it>500)throw ValidationException("$key exceeds 500 C")}
        }
        fun range(a:String,b:String){val min=temp(a);val max=temp(b);if(min!=null&&max!=null&&min>max)throw ValidationException("Temperature range is inverted")}
        range("min_temp","max_temp");range("bed_min_temp","bed_max_temp")
        if("weight" in root.values){val weight=root.int("weight")?:throw ValidationException("weight must be an integer number");if(weight !in 1..100_000)throw ValidationException("weight is outside the supported range")}
        if("additional_color_hexes" in root.values){val colors=(root.values["additional_color_hexes"] as? JsonValue.Arr)?.values?:throw ValidationException("additional_color_hexes must be an array");if(colors.size>4)throw ValidationException("At most four additional colors are supported");colors.forEach{normalizeHex((it as? JsonValue.Str)?.value?:throw ValidationException("Additional colors must be strings"))}}
        DecodeResult.Supported(root.values, payload.copyOf())
      } catch(e: ValidationException) { DecodeResult.Rejected(e.message ?: "Malformed JSON") }
    }

    fun semanticallyMatches(intent: OpenSpoolIntent, actual: ByteArray): Boolean {
        val expected = decode(intent.payloadUnsafe()) as? DecodeResult.Supported ?: return false
        val observed = decode(actual) as? DecodeResult.Supported ?: return false
        return expected.values == observed.values
    }
}

package net.jamesjennison.spoolio.core

sealed interface JsonValue {
    data class Obj(val values: LinkedHashMap<String, JsonValue>) : JsonValue
    data class Arr(val values: List<JsonValue>) : JsonValue
    data class Str(val value: String) : JsonValue
    data class Num(val lexical: String) : JsonValue
    data class Bool(val value: Boolean) : JsonValue
    data object Null : JsonValue
}

class StrictJson(private val maxBytes: Int = 16_384, private val maxDepth: Int = 16) {
    fun parse(bytes: ByteArray): JsonValue {
        if (bytes.size > maxBytes) throw ValidationException("JSON exceeds $maxBytes bytes")
        val text = bytes.toString(Charsets.UTF_8)
        if (!text.toByteArray(Charsets.UTF_8).contentEquals(bytes)) throw ValidationException("Invalid UTF-8")
        val parser = Parser(text, maxDepth)
        return parser.parse()
    }

    private class Parser(private val s: String, private val depthLimit: Int) {
        private var i = 0
        fun parse(): JsonValue { val v = value(0); ws(); if (i != s.length) fail("Trailing data"); return v }
        private fun value(depth: Int): JsonValue {
            if (depth > depthLimit) fail("Nesting limit exceeded")
            ws(); if (i >= s.length) fail("Unexpected end")
            return when (s[i]) {
                '{' -> obj(depth + 1); '[' -> arr(depth + 1); '"' -> JsonValue.Str(string())
                't' -> literal("true", JsonValue.Bool(true)); 'f' -> literal("false", JsonValue.Bool(false)); 'n' -> literal("null", JsonValue.Null)
                '-', in '0'..'9' -> number(); else -> fail("Unexpected character")
            }
        }
        private fun obj(depth: Int): JsonValue.Obj { i++; ws(); val out = linkedMapOf<String, JsonValue>(); if (take('}')) return JsonValue.Obj(out); while (true) { ws(); if (i >= s.length || s[i] != '"') fail("Object key required"); val key = string(); if (out.containsKey(key)) fail("Duplicate key: $key"); ws(); expect(':'); out[key] = value(depth); ws(); if (take('}')) return JsonValue.Obj(out); expect(',') } }
        private fun arr(depth: Int): JsonValue.Arr { i++; ws(); val out = mutableListOf<JsonValue>(); if (take(']')) return JsonValue.Arr(out); while (true) { out += value(depth); ws(); if (take(']')) return JsonValue.Arr(out); expect(',') } }
        private fun string(): String {
            expect('"'); val out = StringBuilder()
            while (i < s.length) {
                val c = s[i++]
                when {
                    c == '"' -> return out.toString()
                    c == '\\' -> {
                        if (i >= s.length) fail("Bad escape")
                        when (val e=s[i++]) {
                            '"','\\','/' -> out.append(e); 'b' -> out.append('\b'); 'f' -> out.append('\u000C'); 'n' -> out.append('\n'); 'r' -> out.append('\r'); 't' -> out.append('\t')
                            'u' -> {
                                val first=unicodeEscape()
                                if (first.isHighSurrogate()) {
                                    if (i+2>s.length || s[i]!='\\' || s[i+1]!='u') fail("High surrogate must be paired")
                                    i+=2; val second=unicodeEscape(); if(!second.isLowSurrogate()) fail("High surrogate must be paired")
                                    out.append(first).append(second)
                                } else if(first.isLowSurrogate()) fail("Lone low surrogate") else out.append(first)
                            }
                            else -> fail("Bad escape")
                        }
                    }
                    c.code < 0x20 -> fail("Control character")
                    c.isSurrogate() -> fail("Unpaired surrogate")
                    else -> out.append(c)
                }
            }
            fail("Unterminated string")
        }
        private fun unicodeEscape():Char { if(i+4>s.length) fail("Bad unicode escape"); val hex=s.substring(i,i+4); val value=hex.toIntOrNull(16)?.toChar() ?: fail("Bad unicode escape"); i+=4; return value }
        private fun number(): JsonValue.Num { val start=i; if(take('-') && i>=s.length) fail("Bad number"); if(take('0')) { if(i<s.length && s[i] in '0'..'9') fail("Leading zero") } else { digits() }; if(take('.')) digits(); if(i<s.length && (s[i]=='e'||s[i]=='E')) { i++; if(i<s.length&&(s[i]=='+'||s[i]=='-')) i++; digits() }; if(i-start>128) fail("Number is too long"); return JsonValue.Num(s.substring(start,i)) }
        private fun digits() { val start=i; while(i<s.length&&s[i] in '0'..'9') i++; if(i==start) fail("Digit required") }
        private fun <T:JsonValue> literal(word:String,v:T):T { if(!s.startsWith(word,i)) fail("Bad literal"); i+=word.length; return v }
        private fun ws(){ while(i<s.length&&s[i] in " \n\r\t") i++ }
        private fun take(c:Char)=if(i<s.length&&s[i]==c){i++;true}else false
        private fun expect(c:Char){ if(!take(c)) fail("Expected $c") }
        private fun fail(message:String):Nothing=throw ValidationException("$message at offset $i")
    }
}

fun JsonValue.Obj.string(key: String): String? = (values[key] as? JsonValue.Str)?.value
fun JsonValue.Obj.int(key: String): Int? = (values[key] as? JsonValue.Num)?.lexical?.toBigDecimalOrNull()?.let { runCatching { it.intValueExact() }.getOrNull() }
fun JsonValue.Obj.decimal(key: String): String? = (values[key] as? JsonValue.Num)?.lexical

fun encodeJsonObject(values: Map<String, Any>): ByteArray {
    fun quote(s: String) = buildString { append('"'); s.forEach { c -> when(c) { '"' -> append("\\\""); '\\' -> append("\\\\"); '\n' -> append("\\n"); '\r' -> append("\\r"); '\t' -> append("\\t"); else -> if(c.code<32) append("\\u%04x".format(c.code)) else append(c) } }; append('"') }
    val text = values.entries.joinToString(prefix="{", postfix="}", separator=",") { (k,v) -> quote(k)+":"+when(v){ is String -> quote(v); is Number, is Boolean -> v.toString(); is List<*> -> v.joinToString(prefix="[",postfix="]") { quote(it.toString()) }; else -> error("Unsupported JSON value") } }
    return text.toByteArray(Charsets.UTF_8)
}

package net.jamesjennison.spoolio.core

enum class WritePhase { DRAFT, AWAITING_TAG, INSPECTING, NEEDS_OVERWRITE_CONSENT, WRITING, VERIFYING, VERIFIED, CANCELLED, REJECTED, FAILED_BEFORE_WRITE, WRITE_OUTCOME_UNKNOWN, UNRESOLVED_ARCHIVED }
class TagRecord(val tnf:Int,val mime:String,payload:ByteArray){private val frozen=payload.copyOf();val payload:ByteArray get()=frozen.copyOf();internal fun payloadUnsafe()=frozen}
class TagSnapshot(uid:ByteArray,val writable:Boolean,val maxNdefSize:Int,records:List<TagRecord>){private val frozenUid=uid.copyOf();val uid:ByteArray get()=frozenUid.copyOf();val records=records.map{TagRecord(it.tnf,it.mime,it.payload)};internal fun uidUnsafe()=frozenUid}
data class WriteState(val phase: WritePhase, val intent: OpenSpoolIntent? = null, private val frozenUid: ByteArray? = null, val detail: String = "") { val uid:ByteArray? get()=frozenUid?.copyOf(); internal fun uidUnsafe()=frozenUid }

class WriteStateMachine {
    var state = WriteState(WritePhase.DRAFT); private set
    private var approvedExistingFingerprint:ByteArray?=null
    private var expectedPayload:ByteArray?=null
    fun arm(intent: OpenSpoolIntent) { require(state.phase in setOf(WritePhase.DRAFT,WritePhase.CANCELLED,WritePhase.REJECTED,WritePhase.FAILED_BEFORE_WRITE,WritePhase.UNRESOLVED_ARCHIVED));approvedExistingFingerprint=null;pendingConsentFingerprint=null;expectedPayload=null;state=WriteState(WritePhase.AWAITING_TAG,intent,detail="Tap an NTAG215") }
    fun inspected(tag: TagSnapshot, ndefMessageSize: Int) {
        val intent=state.intent ?: error("No intent"); require(state.phase==WritePhase.AWAITING_TAG || state.phase==WritePhase.INSPECTING || state.phase==WritePhase.NEEDS_OVERWRITE_CONSENT)
        state=state.copy(phase=WritePhase.INSPECTING,frozenUid=tag.uid,detail="Inspecting writable capacity")
        if(!tag.writable) { state=state.copy(phase=WritePhase.REJECTED,detail="Tag is read-only"); return }
        if(ndefMessageSize>tag.maxNdefSize) { state=state.copy(phase=WritePhase.REJECTED,detail="Message needs $ndefMessageSize bytes; tag reports ${tag.maxNdefSize}"); return }
        val fingerprint=tagFingerprint(tag)
        if(tag.records.isNotEmpty()&&(approvedExistingFingerprint==null||!fingerprint.contentEquals(approvedExistingFingerprint))) { approvedExistingFingerprint=null;pendingConsentFingerprint=fingerprint;state=state.copy(phase=WritePhase.NEEDS_OVERWRITE_CONSENT,detail="Existing content requires approval bound to this tag and content");return }
        pendingConsentFingerprint=null
        expectedPayload=intent.payload
        state=state.copy(phase=WritePhase.WRITING,detail="Keep tag in place")
    }
    fun approveOverwrite(){require(state.phase==WritePhase.NEEDS_OVERWRITE_CONSENT);approvedExistingFingerprint=pendingConsentFingerprint?.copyOf()?:error("No inspected content");state=state.copy(phase=WritePhase.AWAITING_TAG,detail="Approval recorded. Re-tap the same unchanged tag.")}
    fun writeReturned() { require(state.phase==WritePhase.WRITING); state=state.copy(phase=WritePhase.VERIFYING,detail="Remove and re-present only if asked") }
    fun writeInterrupted(reason:String) { require(state.phase==WritePhase.WRITING||state.phase==WritePhase.VERIFYING); state=state.copy(phase=WritePhase.WRITE_OUTCOME_UNKNOWN,detail="$reason. Re-tap for read-only reconciliation; no rewrite will occur.") }
    fun writeFailedBeforeCall(reason:String) { require(state.phase==WritePhase.WRITING); state=state.copy(phase=WritePhase.FAILED_BEFORE_WRITE,detail=reason) }
    fun rejectBeforeWrite(reason:String){require(state.phase in setOf(WritePhase.AWAITING_TAG,WritePhase.INSPECTING,WritePhase.NEEDS_OVERWRITE_CONSENT));state=state.copy(phase=WritePhase.REJECTED,detail=reason)}
    fun reconciled(tag: TagSnapshot) {
        require(state.phase==WritePhase.VERIFYING||state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN)
        val intendedUid=state.uid
        if(intendedUid==null||!intendedUid.contentEquals(tag.uid)) { state=state.copy(phase=WritePhase.WRITE_OUTCOME_UNKNOWN,detail="A different tag was presented"); return }
        val intent=state.intent
        val record=tag.records.singleOrNull()
        val matches=record!=null&&record.tnf==2&&record.mime==OpenSpoolCodec.MIME&&(if(intent!=null)OpenSpoolCodec.semanticallyMatches(intent,record.payloadUnsafe())else expectedPayload?.let{expected->semanticPayloadsMatch(expected,record.payloadUnsafe())}==true)
        state=if(matches) state.copy(phase=WritePhase.VERIFIED,detail="Fresh one-record NDEF message matches the frozen write intent") else state.copy(phase=WritePhase.WRITE_OUTCOME_UNKNOWN,detail="Fresh complete NDEF message does not match; no automatic rewrite")
    }
    fun restoreUnknown(uid:ByteArray,payload:ByteArray){require(state.phase==WritePhase.DRAFT);expectedPayload=payload.copyOf();state=WriteState(WritePhase.WRITE_OUTCOME_UNKNOWN,null,uid.copyOf(),"A prior write may have reached the tag. Re-tap for read-only reconciliation.")}
    fun unknownReadFailed(reason:String){require(state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN);state=state.copy(detail="$reason. The outcome remains unknown; re-tap the same tag for read-only reconciliation.")}
    fun archiveUnknown(){require(state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN);state=WriteState(WritePhase.UNRESOLVED_ARCHIVED,detail="Unresolved write archived without claiming cancellation or verification")}
    fun cancel() { if(state.phase==WritePhase.WRITING||state.phase==WritePhase.VERIFYING||state.phase==WritePhase.WRITE_OUTCOME_UNKNOWN) { if(state.phase!=WritePhase.WRITE_OUTCOME_UNKNOWN)writeInterrupted("Operation interrupted") } else state=state.copy(phase=WritePhase.CANCELLED,detail="Cancelled before writing") }

    private fun semanticPayloadsMatch(a:ByteArray,b:ByteArray):Boolean{val x=OpenSpoolCodec.decode(a) as? DecodeResult.Supported?:return false;val y=OpenSpoolCodec.decode(b) as? DecodeResult.Supported?:return false;return x.values==y.values}
    private fun tagFingerprint(tag:TagSnapshot)=tagFingerprint(tag.uidUnsafe(),tag.records)
    private fun tagFingerprint(uid:ByteArray,records:List<TagRecord>):ByteArray {val digest=java.security.MessageDigest.getInstance("SHA-256");fun sized(bytes:ByteArray){digest.update(java.nio.ByteBuffer.allocate(4).putInt(bytes.size).array());digest.update(bytes)};sized(uid);digest.update(java.nio.ByteBuffer.allocate(4).putInt(records.size).array());records.forEach{digest.update(java.nio.ByteBuffer.allocate(4).putInt(it.tnf).array());sized(it.mime.encodeToByteArray());sized(it.payloadUnsafe())};return digest.digest()}
    private var pendingConsentFingerprint:ByteArray?=null
}

