package net.jamesjennison.spoolio.core
import java.nio.file.Files
import java.security.MessageDigest
import kotlin.test.*

class CatalogGenerationStoreTest {
    @Test fun `corrupt replacement retains prior generation`() {
        val dir=Files.createTempDirectory("spoolio-generation-test"); val store=CatalogGenerationStore(dir); val good="catalog-v1".encodeToByteArray()
        val sha=MessageDigest.getInstance("SHA-256").digest(good).joinToString(""){"%02x".format(it)}
        store.install("v1",good,sha){Files.size(it)>0}; assertEquals("v1",store.active()?.generation)
        assertFails { store.install("v2","broken".encodeToByteArray(),sha){true} }
        assertEquals("v1",store.active()?.generation); assertContentEquals(good,Files.readAllBytes(store.active()!!.artifact))
    }
    @Test fun `failed validation never changes pointer`() {
        val dir=Files.createTempDirectory("spoolio-generation-test"); val store=CatalogGenerationStore(dir); val bytes="x".encodeToByteArray(); val sha=MessageDigest.getInstance("SHA-256").digest(bytes).joinToString(""){"%02x".format(it)}
        assertFails { store.install("v1",bytes,sha){false} }; assertNull(store.active())
    }
}

package net.jamesjennison.spoolio.core

import kotlin.test.*

class OpenSpoolCodecTest {
    private fun record(diameter:String="1.75",min:Int?=230,max:Int?=260)=FilamentRecord(
        "14417b3a-38d3-4643-ace8-40bdc9b7ecf3","4f6c118e-7196-4e13-9345-2f263cf0b430","5a04c396-3b00-474a-9af8-d6a09018d85f",
        FieldValue("SUNLU","OFD"),FieldValue("ABS","OFD"),FieldValue("ABS","OFD"),FieldValue("Orange","OFD"),FieldValue("#FF8E24","OFD"),FieldValue(diameter,"OFD"),FieldValue(1000,"OFD"),min?.let{FieldValue(it,"OFD")},max?.let{FieldValue(it,"OFD")},FieldValue(90,"OFD"),FieldValue(110,"OFD"),sourceRevision="e3888b68",provenance=Provenance.CATALOG)
    @Test fun `paxx uses decimal mm and round trips semantically`() { val intent=OpenSpoolCodec.encode(record(),OpenSpoolProfile.PAXX); assertContains(intent.payload.decodeToString(),"\"diameter\":\"1.75\""); assertTrue(OpenSpoolCodec.semanticallyMatches(intent,intent.payload)) }
    @Test fun `omission preview follows actual serialized fields`() {val missing=OpenSpoolCodec.encode(record(min=null,max=null),OpenSpoolProfile.PAXX);assertContains(missing.omittedFields,"nozzleMin");assertContains(missing.omittedFields,"nozzleMax");val canonical=OpenSpoolCodec.encode(record(),OpenSpoolProfile.CANONICAL);assertContains(canonical.omittedFields,"diameter");assertContains(canonical.omittedFields,"product")}
    @Test fun `legacy diameter is rejected`() { assertFailsWith<ValidationException>{OpenSpoolCodec.encode(record("175"),OpenSpoolProfile.PAXX)} }
    @Test fun `inverted temperatures are rejected`() { assertFailsWith<ValidationException>{OpenSpoolCodec.encode(record(min=260,max=230),OpenSpoolProfile.CANONICAL)} }
    @Test fun `duplicate keys are rejected`() { assertIs<DecodeResult.Rejected>(OpenSpoolCodec.decode("""{"protocol":"openspool","protocol":"openspool","version":"1.0"}""".encodeToByteArray())) }
    @Test fun `unknown version and fields are read only`() {
        assertIs<DecodeResult.ReadOnly>(OpenSpoolCodec.decode("""{"protocol":"openspool","version":"2.0"}""".encodeToByteArray()))
        assertIs<DecodeResult.ReadOnly>(OpenSpoolCodec.decode("""{"protocol":"openspool","version":"1.0","future":1}""".encodeToByteArray()))
    }
    @Test fun `mandatory fields and exact json types are enforced`() {
        listOf(
            """{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":"FF0000"}""",
            """{"protocol":"openspool","version":"1.0","type":1,"color_hex":"FF0000","brand":"B"}""",
            """{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":1,"brand":"B"}""",
            """{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":"FF0000","brand":"B","diameter":1.75}""",
            """{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":"FF0000","brand":"B","diameter":"175"}""",
            """{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":"FF0000","brand":"B","min_temp":230}""",
            """{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":"FF0000","brand":"B","max_temp":"501"}""",
            """{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":"FF0000","brand":"B","weight":-1}"""
        ).forEach { assertIs<DecodeResult.Rejected>(OpenSpoolCodec.decode(it.encodeToByteArray()),it) }
    }
    @Test fun `alpha is preserved read only and extra colors are not truncated`() {
        assertIs<DecodeResult.ReadOnly>(OpenSpoolCodec.decode("""{"protocol":"openspool","version":"1.0","type":"PLA","color_hex":"FF0000","brand":"B","alpha":255}""".encodeToByteArray()))
        assertFailsWith<ValidationException>{OpenSpoolCodec.encode(record().copy(additionalColors=listOf("000000","111111","222222","333333","444444")),OpenSpoolProfile.PAXX)}
    }
    @Test fun `unicode digits lone surrogate and excessive number are rejected`() {
        listOf("""{"n":١}""","""{"n":${"1".repeat(129)}}""","""{"s":"\uD800"}""").forEach{assertFailsWith<ValidationException>{StrictJson().parse(it.encodeToByteArray())}}
        val paired=StrictJson().parse("""{"s":"\uD83D\uDE00"}""".encodeToByteArray()) as JsonValue.Obj
        assertEquals("😀",paired.string("s"))
    }
    @Test fun `utf8 capacity counts bytes`() { val r=record().copy(brand=FieldValue("Märkä","custom")); val intent=OpenSpoolCodec.encode(r,OpenSpoolProfile.CANONICAL); assertTrue(intent.payload.size>intent.payload.decodeToString().length) }
    @Test fun optionalLabelFieldsRemainAbsentRatherThanFabricated() {
        val sparse=record().copy(product=FieldValue("","tag"),colorName=FieldValue("","tag"))
        val canonical=OpenSpoolCodec.encode(sparse,OpenSpoolProfile.CANONICAL)
        val paxx=OpenSpoolCodec.encode(sparse,OpenSpoolProfile.PAXX)
        assertFalse(canonical.payload.decodeToString().contains("subtype"))
        assertFalse(paxx.payload.decodeToString().contains("subtype"))
    }
}

package net.jamesjennison.spoolio.core
import kotlin.test.*

class WriteStateMachineTest {
    private val record=FilamentRecord("p",null,null,FieldValue("B","x"),FieldValue("PLA","x"),FieldValue("P","x"),FieldValue("Red","x"),FieldValue("FF0000","x"),FieldValue("1.75","x"),FieldValue(1000,"x"),null,null,null,null,sourceRevision="r",provenance=Provenance.CUSTOM)
    private val intent=OpenSpoolCodec.encode(record,OpenSpoolProfile.CANONICAL)
    private fun record(payload:ByteArray=intent.payload,mime:String=OpenSpoolCodec.MIME,tnf:Int=2)=TagRecord(tnf,mime,payload)
    private fun tag(uid:ByteArray=byteArrayOf(1),writable:Boolean=true,size:Int=500,records:List<TagRecord> = emptyList())=TagSnapshot(uid,writable,size,records)
    @Test fun `only fresh matching complete message verifies`() { val sm=WriteStateMachine(); sm.arm(intent); sm.inspected(tag(),300); sm.writeReturned(); sm.reconciled(tag(records=listOf(record()))); assertEquals(WritePhase.VERIFIED,sm.state.phase) }
    @Test fun `interruption remains unknown and never rewrites`() { val sm=WriteStateMachine(); sm.arm(intent); sm.inspected(tag(),300); sm.writeInterrupted("lost"); assertEquals(WritePhase.WRITE_OUTCOME_UNKNOWN,sm.state.phase); sm.reconciled(tag(records=listOf(record("{}".encodeToByteArray())))); assertEquals(WritePhase.WRITE_OUTCOME_UNKNOWN,sm.state.phase) }
    @Test fun `different uid cannot reconcile`() { val sm=WriteStateMachine(); sm.arm(intent); sm.inspected(tag(),300); sm.writeReturned(); sm.reconciled(tag(byteArrayOf(2),records=listOf(record()))); assertEquals(WritePhase.WRITE_OUTCOME_UNKNOWN,sm.state.phase) }
    @Test fun `existing content consent is bound to uid and content`() { val original=listOf(TagRecord(1,"text/plain",byteArrayOf(1)));val sm=WriteStateMachine();sm.arm(intent);sm.inspected(tag(records=original),300);assertEquals(WritePhase.NEEDS_OVERWRITE_CONSENT,sm.state.phase);sm.approveOverwrite();sm.inspected(tag(records=listOf(TagRecord(1,"text/plain",byteArrayOf(2)))),300);assertEquals(WritePhase.NEEDS_OVERWRITE_CONSENT,sm.state.phase) }
    @Test fun `approved unchanged content can write`() { val existing=listOf(TagRecord(1,"text/plain",byteArrayOf(1)));val sm=WriteStateMachine();sm.arm(intent);sm.inspected(tag(records=existing),300);sm.approveOverwrite();sm.inspected(tag(records=existing),300);assertEquals(WritePhase.WRITING,sm.state.phase) }
    @Test fun `extra record wrong tnf or mime cannot verify`() { listOf(tag(records=listOf(record(),TagRecord(1,"text/plain",byteArrayOf(1)))),tag(records=listOf(record(tnf=1))),tag(records=listOf(record(mime="Application/JSON")))).forEach{observed->val sm=WriteStateMachine();sm.arm(intent);sm.inspected(tag(),300);sm.writeReturned();sm.reconciled(observed);assertEquals(WritePhase.WRITE_OUTCOME_UNKNOWN,sm.state.phase)} }
    @Test fun `restored unknown only reconciles matching uid and complete message`() { val sm=WriteStateMachine();sm.restoreUnknown(byteArrayOf(1),intent.payload);sm.reconciled(tag(records=listOf(record())));assertEquals(WritePhase.VERIFIED,sm.state.phase) }
    @Test fun `intent and snapshots defensively copy byte arrays`() { val payload=intent.payload;payload[0]=0;assertTrue(OpenSpoolCodec.semanticallyMatches(intent,intent.payload));val uid=byteArrayOf(1);val snapshot=tag(uid=uid);uid[0]=2;assertContentEquals(byteArrayOf(1),snapshot.uid) }
    @Test fun `read only and undersized reject before write`() { val a=WriteStateMachine(); a.arm(intent); a.inspected(tag(writable=false),300); assertEquals(WritePhase.REJECTED,a.state.phase); val b=WriteStateMachine(); b.arm(intent); b.inspected(tag(size=10),300); assertEquals(WritePhase.REJECTED,b.state.phase) }
    @Test fun unknownReadFailureRemainsUnknownAndCanBeArchived() { val sm=WriteStateMachine();sm.restoreUnknown(byteArrayOf(1),intent.payload);sm.unknownReadFailed("Tag lost");assertEquals(WritePhase.WRITE_OUTCOME_UNKNOWN,sm.state.phase);sm.archiveUnknown();assertEquals(WritePhase.UNRESOLVED_ARCHIVED,sm.state.phase);sm.arm(intent);assertEquals(WritePhase.AWAITING_TAG,sm.state.phase) }
}

